from lib import *

def _enc(k, plain):
    out = ''
    num = 0
    for i in range(0, len(plain), k):
        num += 1
        part = plain[i:i + k]
        if num % 2 == 1:
            part = part[::-1]
        e = ''
        for c in part:
            o = ord(c)
            if 65 <= o <= 90: e += chr((o - 65 + num) % 26 + 65)
            elif 97 <= o <= 122: e += chr((o - 97 + num) % 26 + 97)
            else: e += c
        out += e
    return f'{k}\n{out}'
_ENC = [_enc(3, 'Meet_me_at_nine'), _enc(1, 'a'), _enc(20, 'Hello'), _enc(2, 'GSA_Python_2026!'), _enc(4, 'The_quick_brown_fox_jumps'), _enc(5, 'Zz_top_XYZ_xyz'), _enc(7, 'exam_is_over_Good_luck_to_you_all')]

